144	\begin{definition}[Pulled-apart Pauli basis measurements]\label{def:tilde-m-measurement}
145		\lean{MIPStarRE.QPBT.tildeM}
146		\leanok
147		\uses{def:s-w-marginals, def:tau-dot-product-projector, def:qld-full-field-decoder}
148		For all $W \in \{X,Z\}$ and $\tilde{u} \in \F_q^{M}$ define the measurement $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ by
149		\begin{equation}\label{eq:tilde_M}
150			\tilde{M}^{W,\tilde{u}}_a = \sum_{g} \hat{S}^W_g \ot \tau_{(\mathrm{Dec}(g) \cdot \tilde{u}) - a}^W(\tilde{u})\;,
151		\end{equation}
