155	\begin{lemma}[Projectivity and completeness of the pulled-apart measurements]\label{lem:tilde-m-projective}
156		\lean{MIPStarRE.QPBT.tildeM_isProj, MIPStarRE.QPBT.sum_tildeM_eq_one}
157		\leanok
