165	\begin{proof}
166		\leanok
167		\uses{def:tilde-m-measurement, lem:s-w-marginals-projective,
168			lem:tau-dot-product-projective}
169		For fixed $W$, $\tilde{u}$, and $a$, each summand in \eqref{eq:tilde_M}
170		is a tensor product of two projections, hence is a projection.
171		If $g\ne g'$, then $\hat{S}^W_g\hat{S}^W_{g'}=0$ because
172		$\{\hat{S}^W_g\}_g$ is a projective measurement. Thus distinct summands
173		in \eqref{eq:tilde_M} are orthogonal, and their sum is a projection.
174		For completeness, fix $g$ and put $c_g=\mathrm{Dec}(g)\cdot\tilde{u}$.
175		The map $a\mapsto c_g-a$ is a bijection of $\F_q$, so
176		\[
177			\sum_a\tau^W_{c_g-a}(\tilde{u})=\Id.
178		\]
179		Interchanging the two finite sums in \eqref{eq:tilde_M} gives
180		\[
181			\sum_a\tilde{M}^{W,\tilde{u}}_a
182			=\sum_g\hat{S}^W_g\ot\Id=\Id.
183		\]
